function article({lang='de',eyebrow,title,lead,answer,read,toc,sections,icon}){
 const en=lang==='en';
 return `<div class="article-hero"><div class="shell article-hero-grid"><div><nav class="breadcrumbs" aria-label="${en?'Breadcrumb':'Brotkrümelnavigation'}"><a href="${en?'/en/':'/'}">${en?'Home':'Startseite'}</a><span>/</span><a href="${en?'/en/help/':'/hilfe/'}">${en?'Guides':'Ratgeber'}</a></nav><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="hero-lead">${lead}</p><div class="article-actions"><a class="button" href="#start">${en?'Start guide':'Anleitung starten'} ${icon('arrow-down')}</a><span>${read}</span></div></div><div class="direct-answer"><span>${icon('check')}</span><p><strong>${en?'In short:':'Kurzantwort:'}</strong> ${answer}</p></div></div></div><div class="article-layout shell"><aside class="toc"><p>${en?'In this guide':'In diesem Ratgeber'}</p>${toc.map(([id,label])=>`<a href="#${id}">${label}</a>`).join('')}</aside><article class="prose">${sections}</article></div>`;
}

function hub({lang='de',title,lead,cards,faq}){
 const en=lang==='en';
 return `<section class="simple-hero"><div class="shell narrow"><p class="eyebrow">${en?'Help centre':'Hilfebereich'}</p><h1>${title}</h1><p class="hero-lead">${lead}</p></div></section><section class="section shell"><div class="guide-grid">${cards.map(c=>`<article class="guide-card"><span>${c.no}</span><p class="kicker">${c.kind}</p><h2>${c.title}</h2><p>${c.text}</p><a class="text-action" href="${c.href}">${en?'Open guide':'Ratgeber öffnen'} →</a></article>`).join('')}</div></section><section class="section faq-section"><div class="shell narrow"><div class="section-heading centered"><p class="kicker">FAQ</p><h2>${en?'Common questions':'Häufige Fragen'}</h2></div><div class="faq-list">${faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`;
}

function simple({eyebrow,title,lead,body}){
 return `<section class="simple-hero"><div class="shell narrow"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="hero-lead">${lead}</p></div></section><div class="shell legal-layout"><article class="prose legal-prose">${body}</article></div>`;
}

export const appStructuredData = ({canonicalBase,playUrl}) => ({
 '@context':'https:'+'//schema.org',
 '@type':'MobileApplication',
 '@id':`${canonicalBase}/#app`,
 name:'FotoSafe',
 applicationCategory:'UtilitiesApplication',
 operatingSystem:'Android 9 or newer',
 installUrl:playUrl
});

export const breadcrumbStructuredData = items => ({
 '@type':'BreadcrumbList',
 itemListElement:items.map((item,index)=>({
  '@type':'ListItem',position:index+1,name:item.name,...(item.item?{item:item.item}:{})
 }))
});

const deHelp=hub({title:'Hilfe, die dich wirklich bis zur Kopie bringt.',lead:'Wähle den passenden Einstieg: kompletter USB-Ablauf, Hardware-Auswahl oder eine robuste Backup-Strategie. Ohne Konto, ohne versteckte Support-Schleife.',cards:[
 {no:'01',kind:'Schritt für Schritt',title:'Android-Fotos auf USB sichern',text:'Vom Anschließen bis zur Stichprobe nach dem Backup – inklusive ehrlicher Dateimanager-Alternative.',href:'/android-fotos-auf-usb-stick-sichern/'},
 {no:'02',kind:'Kauf- und Kompatibilitätshilfe',title:'USB-Stick und OTG-Adapter auswählen',text:'Anschlüsse, Datenfähigkeit, Dateisystem, Strombedarf und Kapazität verständlich prüfen.',href:'/usb-stick-fuer-android-auswaehlen/'},
 {no:'03',kind:'Sicherungswissen',title:'Eine verlässliche Foto-Backup-Strategie',text:'Warum eine USB-Kopie sinnvoll ist – und weshalb eine einzige Kopie trotzdem nicht reicht.',href:'/foto-backup-strategie-android/'},
],faq:[['Löscht FotoSafe Dateien vom Handy?','Nein. FotoSafe kopiert zugängliche Medien auf das gewählte Ziel und löscht die Originale nicht.'],['Warum wird mein USB-Stick nicht angezeigt?','Android muss den Speicher zuerst erkennen. Prüfe Verbindung, einen datenfähigen OTG-Adapter, Strombedarf und die Anzeige im System-Dateimanager.'],['Kann ich FotoSafe ohne Kauf testen?','Ein erfolgreicher Backup-Lauf mit bis zu 100 Medien ist kostenlos. Weitere Läufe erfordern den einmaligen Pro-Kauf über Google Play.'],['Wo bekomme ich persönliche Hilfe?','Nutze zuerst die Fehlerchecks im USB-Ratgeber. Falls das nicht reicht, findest du auf der Supportseite den direkten E-Mail-Kontakt.']]});

const deChoose=({icon})=>article({eyebrow:'Hardware-Ratgeber',title:'USB-Stick für Android auswählen: Was wirklich zusammenpassen muss',lead:'Nicht jeder Stecker garantiert eine funktionierende Datenverbindung. Mit fünf Prüfungen vermeidest du die häufigsten Fehlkäufe.',answer:'Prüfe Anschluss, OTG-Unterstützung, Datenfähigkeit des Adapters, Dateisystem und Kapazität. USB-C direkt ist meist am einfachsten.',read:'Lesedauer: etwa 6 Minuten',icon,toc:[['start','Schnellcheck'],['anschluss','Anschluss & OTG'],['speicher','Kapazität & Dateisystem'],['testen','Vor dem Backup testen'],['probleme','Wenn nichts erscheint']],sections:`<section id="start"><p class="kicker">Schnellcheck</p><h2>Fünf Punkte vor dem Kauf</h2><ul class="check-list"><li>${icon('check')}<span><strong>Stecker:</strong> USB-C direkt oder USB-A über USB-C-OTG.</span></li><li>${icon('check')}<span><strong>Daten statt nur Laden:</strong> Der Adapter muss Datenübertragung unterstützen.</span></li><li>${icon('check')}<span><strong>OTG:</strong> Das Android-Gerät muss USB-Host-Funktionen anbieten.</span></li><li>${icon('check')}<span><strong>Platz:</strong> Freier Speicher sollte deutlich über der angezeigten Backup-Menge liegen.</span></li><li>${icon('check')}<span><strong>Bauform:</strong> Breite Stecker dürfen Hülle oder Nachbaranschlüsse nicht blockieren.</span></li></ul></section><section id="anschluss"><p class="kicker">Verbindung</p><h2>USB-C direkt reduziert Fehlerquellen</h2><p>Ein Dual-Stick mit USB-C und USB-A lässt sich am Handy und später am Computer verwenden. Bei USB-A-Sticks brauchst du einen OTG-Adapter. Ladeadapter oder reine Ladekabel übertragen keine Dateien.</p><div class="callout warning"><strong>„Passt hinein“ reicht nicht.</strong><p>Mechanische Passform sagt nichts über OTG- und Datenunterstützung aus. Prüfe die Herstellerangaben des Handys und des Adapters.</p></div></section><section id="speicher"><p class="kicker">Speicher</p><h2>Kapazität und Dateisystem realistisch planen</h2><p>Fotos benötigen meist weniger Platz als Videos. Kontrolliere die von FotoSafe angezeigte Datenmenge und plane Reserve ein. Externe Datenträger werden je nach Android-Gerät und Dateisystem unterschiedlich unterstützt.</p><p>Formatiere einen vorhandenen Stick niemals nur auf Verdacht: Dabei werden alle darauf gespeicherten Dateien gelöscht. Sichere den Inhalt vorher.</p></section><section id="testen"><p class="kicker">Vorbereitung</p><h2>Erkennung vor dem großen Lauf prüfen</h2><ol><li>Handy entsperren und Stick verbinden.</li><li>Einige Sekunden warten.</li><li>Im Android-Dateimanager nach einem USB-Speicher suchen.</li><li>Eine kleine Testdatei öffnen oder kopieren.</li><li>Erst dann FotoSafe starten und das USB-Ziel wählen.</li></ol></section><section id="probleme"><p class="kicker">Diagnose</p><h2>USB wird nicht angezeigt?</h2><p>Verbindung neu stecken, Hülle entfernen, anderen datenfähigen Adapter testen und den Strombedarf reduzieren. Wenn Android den Datenträger selbst nicht sieht, kann FotoSafe ihn ebenfalls nicht auswählen.</p><a class="button" href="/android-fotos-auf-usb-stick-sichern/#probleme">Zur ausführlichen Fehlerhilfe ${icon('arrow')}</a></section>`});

const deStrategy=({icon})=>article({eyebrow:'Backup-Grundlagen',title:'Foto-Backup auf Android: So wird aus einer Kopie eine Strategie',lead:'Eine lokale USB-Kopie ist wertvoll, aber kein einzelner Datenträger ist unfehlbar. Entscheidend sind mehrere Kopien, Kontrolle und ein wiederholbarer Rhythmus.',answer:'Behalte die Originale, erstelle mindestens eine zusätzliche Kopie und bewahre eine weitere wichtige Kopie an einem anderen Ort auf.',read:'Lesedauer: etwa 7 Minuten',icon,toc:[['start','3-2-1-Prinzip'],['rhythmus','Rhythmus'],['kontrolle','Kontrolle'],['risiken','Risiken'],['checkliste','Checkliste']],sections:`<section id="start"><p class="kicker">Das Prinzip</p><h2>Drei Kopien, zwei Medien, ein anderer Ort</h2><p>Die bekannte 3-2-1-Regel ist eine Orientierung: drei Kopien wichtiger Daten, auf mindestens zwei unterschiedlichen Speichertypen, davon eine räumlich getrennt. Für private Fotos kann das Handy plus USB-Kopie plus eine weitere vertrauenswürdige Sicherung bedeuten.</p><div class="callout success"><strong>FotoSafe ist ein Baustein.</strong><p>Die App erstellt eine selbst verwahrte USB-Kopie. Sie ersetzt nicht automatisch jede andere Sicherung.</p></div></section><section id="rhythmus"><p class="kicker">Routine</p><h2>Ein einfacher Rhythmus schlägt den perfekten Plan</h2><p>Sichere nach wichtigen Ereignissen und zusätzlich regelmäßig. Verwende möglichst dasselbe geprüfte Ziel. FotoSafe überspringt bereits gesicherte Dateien, sodass spätere Läufe auf neue Medien fokussiert bleiben.</p></section><section id="kontrolle"><p class="kicker">Vertrauen durch Prüfung</p><h2>Erfolgsmeldung plus Stichprobe</h2><p>Lass den Stick bis zum Abschluss verbunden. Öffne anschließend einige neue Fotos und große Videos direkt vom Zielmedium. Prüfe gelegentlich auch ältere Dateien.</p></section><section id="risiken"><p class="kicker">Grenzen</p><h2>USB-Sticks können ausfallen, verloren gehen oder beschädigt werden</h2><p>Lagere nicht jede Kopie in derselben Tasche oder Wohnungsecke. Ein Diebstahl, Wasser- oder Brandschaden kann sonst alle Medien gleichzeitig treffen. Besonders private Sticks sollten physisch geschützt werden.</p></section><section id="checkliste"><p class="kicker">Kurzliste</p><h2>Deine nächste Sicherung</h2><ul class="check-list"><li>${icon('check')}<span>Genügend freien Platz prüfen.</span></li><li>${icon('check')}<span>USB-Ziel und Medienauswahl kontrollieren.</span></li><li>${icon('check')}<span>Während des Laufs nicht abziehen.</span></li><li>${icon('check')}<span>Neue Dateien am Ziel stichprobenartig öffnen.</span></li><li>${icon('check')}<span>Eine weitere Kopie getrennt aufbewahren.</span></li></ul><a class="button" href="/android-fotos-auf-usb-stick-sichern/">USB-Anleitung öffnen ${icon('arrow')}</a></section>`});

const deSupport=simple({eyebrow:'Direkter Support',title:'Wie können wir dir helfen?',lead:'Die meisten USB-Probleme lassen sich mit den Diagnose-Schritten lösen. Wenn nicht, erreichst du FotoSafe direkt per E-Mail.',body:`<section><h2>Zuerst prüfen</h2><ul><li>Wird der Stick im Android-Dateimanager angezeigt?</li><li>Ist der OTG-Adapter datenfähig?</li><li>Zeigt der Android-Dateidialog wirklich den USB-Speicher als Ziel?</li><li>Ist genügend freier Speicher vorhanden?</li></ul><a class="button" href="/android-fotos-auf-usb-stick-sichern/#probleme">Zur Fehlerhilfe</a></section><section><h2>Direkter Kontakt</h2><p>Nenne bitte Handymodell, Android-Version, FotoSafe-Version, Stick/Adapter und den Schritt, an dem es hängt. Sende keine privaten Fotos, Videos oder vertraulichen Dateien.</p><p><a class="button" href="mailto:fotosafe@weidisoft.net?subject=FotoSafe%20Support">fotosafe@weidisoft.net</a></p><div class="callout success"><strong>Kein Webformular.</strong><p>Die Website erfasst deinen Nachrichtentext nicht und setzt keine Analyse-Cookies.</p></div></section>`});

const deImprint=simple({eyebrow:'Anbieterinformationen',title:'Impressum',lead:'Angaben zum Anbieter der FotoSafe-Website und der Android-App FotoSafe.',body:`<section><h2>Diensteanbieter und Medieninhaber</h2><address>Peter Weitgasser<br>Bsuch 123<br>A-5760 Saalfelden<br>Österreich</address></section><section><h2>Kontakt</h2><p><a href="mailto:fotosafe@weidisoft.net">fotosafe@weidisoft.net</a></p></section><section><h2>Inhaltliche Ausrichtung</h2><p>Informationen, Hilfestellungen und Support rund um die Android-App FotoSafe und die lokale Sicherung von Fotos und Videos.</p></section>`});

const dePrivacy=simple({eyebrow:'Datenschutz',title:'Datenschutzerklärung für FotoSafe-App und Website',lead:'Klare Trennung: Die App verarbeitet Medien lokal. Die Website benötigt weder Konto noch Analyse-Cookies.',body:`<p><strong>Stand:</strong> 12. September 2026 · <strong>App:</strong> FotoSafe · <strong>Paket:</strong> <code>at.weidi.fotobackup</code></p><section><h2>1. Kurzfassung</h2><ul><li>kein FotoSafe-Konto, keine Werbung und kein Tracking in der App,</li><li>kein Upload deiner Fotos oder Videos auf Server des App-Anbieters,</li><li>keine Löschung der Originaldateien,</li><li>keine Websiteanalyse und keine Analyse-Cookies auf dieser Website.</li></ul></section><section><h2>2. Verantwortlicher</h2><address>Peter Weitgasser<br>Bsuch 123<br>A-5760 Saalfelden<br>Österreich<br><a href="mailto:privacy@weidisoft.net">privacy@weidisoft.net</a></address></section><section><h2>3. Lokale Verarbeitung in der App</h2><p>FotoSafe liest – nach deiner Android-Freigabe – Fotos, Videos und dazugehörige Dateiinformationen, um sie auf den ausdrücklich ausgewählten Speicherort zu kopieren. Am Ziel entstehen Medienkopien sowie lokale Protokoll- und Indexinformationen. Zielauswahl, letzter Backup-Status und Test-/Pro-Status werden lokal gespeichert.</p><p>Die App verwendet keinen allgemeinen All-Files-Zugriff. Ab Android 14 kann Teilzugriff nur ausgewählte Medien umfassen; vollständiger Zugriff muss für ein vollständiges Backup selbst in den Android-Einstellungen erlaubt werden.</p></section><section><h2>4. Google Play und Pro-Kauf</h2><p>Installation, einmaliger Pro-Kauf und Kaufwiederherstellung werden über Google Play abgewickelt. Google verarbeitet dafür erforderliche Konto-, Zahlungs- und Kaufdaten nach eigenen Datenschutzbestimmungen. FotoSafe erhält Produkt-, Preis- und Kaufstatusinformationen, aber keine Kreditkartendaten.</p></section><section><h2>5. Website und Hosting</h2><p>Diese statische Website wird über Cloudflare Pages ausgeliefert. Dabei können technisch erforderliche Verbindungs- und Sicherheitsdaten, insbesondere die IP-Adresse, durch Cloudflare verarbeitet werden. Es werden keine Analyse-, Werbe- oder Tracking-Skripte eingesetzt. Weitere Informationen: <a href="https://www.cloudflare.com/privacypolicy/" rel="noopener noreferrer">Cloudflare Privacy Policy</a>.</p></section><section><h2>6. Löschen und Rechte</h2><p>Backup-Kopien löschst du selbst am gewählten Zielmedium. Lokale App-Daten können über die Android-Einstellungen oder Deinstallation entfernt werden; ein Google-Play-Kauf bleibt im Google-Konto und kann wiederhergestellt werden.</p><p>Für Auskunft, Berichtigung, Löschung, Einschränkung oder Widerspruch schreibe an <a href="mailto:privacy@weidisoft.net">privacy@weidisoft.net</a>. Außerdem besteht ein Beschwerderecht bei der Österreichischen Datenschutzbehörde.</p></section>`});

const enBadge=(playUrl)=>`<a class="play-badge" href="${playUrl}" target="_blank" rel="noopener noreferrer" aria-label="Install FotoSafe from Google Play — opens in a new tab"><img src="/assets/google-play/get-it-on-google-play-en.png" alt="Get it on Google Play" width="194" height="75"></a>`;

const enHome=({icon,playUrl,zoomImage})=>{const badge=enBadge(playUrl);return `<section class="hero shell"><div class="hero-copy"><p class="eyebrow">Android photo backup · straight to USB</p><h1>Your photos.<br><span>Your copy.</span><br>Your USB drive.</h1><p class="hero-lead">FotoSafe guides you through a local copy of your photos and videos — without a computer or FotoSafe media cloud. Originals stay on your phone.</p><div class="hero-actions">${badge}<a class="text-action" href="#how">How it works ${icon('arrow')}</a></div><p class="trial-note"><strong>Try it fairly:</strong> one successful backup run with up to 100 photos or videos is free. FotoSafe Pro then unlocks further runs with a one-time Google Play purchase — no subscription.</p></div><div class="hero-visual">${zoomImage('/assets/01-three-guided-steps-to-usb-en.webp','FotoSafe start screen showing the three-step USB backup flow','Current FotoSafe app screen.','hero-shot')}<span class="proof-chip chip-local">${icon('usb')} Local USB copy</span><span class="proof-chip chip-copy">${icon('copy')} Originals stay</span></div></section><section class="trust-strip"><div class="shell trust-grid"><span>${icon('usb')} Direct USB copy</span><span>${icon('shield')} No FotoSafe account</span><span>${icon('refresh')} Skips backed-up files</span><span>${icon('card')} One-time Pro purchase</span></div></section><section class="section shell intro-section"><div class="section-heading"><p class="kicker">A backup you can see</p><h2>Not somewhere. Exactly where you choose.</h2><p>FotoSafe copies accessible photos and videos to USB storage selected by you. It does not move files, delete originals or upload your media.</p></div><div class="value-panel"><div class="value-mark">01</div><p>Useful when you want an additional local copy without switching on a computer.</p></div></section><section class="section process-section" id="how"><div class="shell"><div class="section-heading light"><p class="kicker">Three clear steps</p><h2>From phone to USB — guided, not guessed.</h2></div><ol class="process-grid"><li><span>1</span><div>${icon('plug')}<h3>Connect USB</h3><p>Connect USB-C directly or use a data-capable OTG adapter.</p></div></li><li><span>2</span><div>${icon('check')}<h3>Review selection</h3><p>Allow media access, select the USB destination and check the preview.</p></div></li><li><span>3</span><div>${icon('copy')}<h3>Copy and verify</h3><p>Keep the drive connected and check important files afterwards.</p></div></li></ol><a class="button button-light" href="/en/guides/back-up-android-photos-to-usb/">Read the complete guide ${icon('arrow')}</a></div></section><section class="section shell"><div class="section-heading centered"><p class="kicker">See before you copy</p><h2>Three screens. One clear workflow.</h2><p>Start with the guided flow, review destination and file counts, then choose additional folders in Expert mode when needed.</p></div><div class="shot-grid">${zoomImage('/assets/01-three-guided-steps-to-usb-en.webp','FotoSafe guided USB backup start screen','Choose the guided three-step flow.')} ${zoomImage('/assets/02-review-before-backup-en.webp','FotoSafe review screen with destination and media counts','Review the copy before it starts.','featured')} ${zoomImage('/assets/03-expert-mode-sources-en.webp','FotoSafe Expert mode source selection','Add accessible folders in Expert mode.')}</div></section><section class="section shell split-section"><div><p class="kicker">One more local copy</p><h2>Useful protection without replacing a complete backup plan.</h2><p>Your phone remains the original location. The USB drive becomes an additional copy you control. For irreplaceable memories, keep another verified copy in a separate place as well.</p></div><div class="safety-note" role="note"><span>${icon('shield')}</span><h3>Copy first, verify second</h3><p>Open several photos and large videos from the USB drive before deleting anything from another device or location.</p></div></section><section class="section faq-section"><div class="shell narrow"><div class="section-heading"><p class="kicker">Frequently asked</p><h2>Short answers before you start</h2></div><div class="faq-list"><details><summary>Does FotoSafe delete my originals?</summary><p>No. FotoSafe copies accessible photos and videos to the selected destination; originals remain on the phone.</p></details><details><summary>Does FotoSafe upload my media?</summary><p>No FotoSafe media cloud is involved. The app copies directly to storage selected through Android.</p></details><details><summary>What is included in the free trial?</summary><p>One successful backup run with up to 100 media files. Further runs require FotoSafe Pro.</p></details><details><summary>Is FotoSafe Pro a subscription?</summary><p>No. Pro is a one-time Google Play in-app purchase. Google Play shows the current price.</p></details><details><summary>What if Android does not show my USB drive?</summary><p>Check the drive in Android's file manager, reconnect it and verify that any OTG adapter supports data rather than charging only.</p></details></div></div></section><section class="section shell price-section"><div><p class="kicker">Clear trial. Clear choice.</p><h2>One run free.<br>Then Pro once.</h2></div><div class="price-card"><p class="price-label">Free trial run</p><p class="price">Up to <strong>100</strong> media files</p><p>One successful backup run, not 100 files on every run.</p><hr><p class="price-label">FotoSafe Pro</p><p class="price"><strong>One-time purchase</strong></p><p>Further backup runs, no subscription. Google Play shows the current price.</p>${badge}</div></section><section class="final-cta"><div class="shell final-grid"><div><p class="kicker">Ready for your own copy?</p><h2>Connect USB.<br>Try FotoSafe.</h2></div><div>${badge}<a href="/en/help/">Read help and guides first</a></div></div></section>`};

const enHelp=hub({lang:'en',title:'Help that gets you all the way to a verified copy.',lead:'Choose the right starting point: complete USB workflow, hardware selection or a resilient backup strategy.',cards:[{no:'01',kind:'Step by step',title:'Back up Android photos to USB',text:'From connection to verification, including an honest file-manager alternative.',href:'/en/guides/back-up-android-photos-to-usb/'},{no:'02',kind:'Compatibility guide',title:'Choose a USB drive and OTG adapter',text:'Check connectors, data support, file systems, power and capacity.',href:'/en/guides/choose-usb-drive-for-android/'},{no:'03',kind:'Backup basics',title:'Build a reliable photo backup strategy',text:'Why a USB copy helps — and why one copy is still not enough.',href:'/en/guides/android-photo-backup-strategy/'}],faq:[['Does FotoSafe delete originals?','No. FotoSafe copies accessible media to your selected destination and does not delete the originals.'],['Why is my USB drive missing?','Android must detect it first. Check the connection, a data-capable OTG adapter, power requirements and the system file manager.'],['Can I try FotoSafe without paying?','One successful backup run with up to 100 media files is free. Further runs require the one-time Pro purchase.'],['Where can I get personal help?','Start with the troubleshooting steps in the USB guide. If they do not solve it, the Support page provides the direct email contact.']]});

const enUsb=({icon,zoomImage})=>article({lang:'en',eyebrow:'Step-by-step guide',title:'Back up Android photos to a USB drive — without a computer',lead:'You need a compatible Android device, USB storage recognised by Android and, where needed, a data-capable OTG adapter.',answer:'Connect the drive, select it as the destination in FotoSafe, review the media and start copying. The Android picker must show USB storage, not internal storage.',read:'Reading time: about 8 minutes',icon,toc:[['start','Requirements'],['steps','Five steps'],['verify','Verify the copy'],['alternative','File-manager alternative'],['repeat','Back up again'],['problems','Troubleshooting']],sections:`<section id="start"><p class="kicker">Preparation</p><h2>What you need</h2><ul class="check-list"><li>${icon('check')}<span>Android 9 or later with USB host/OTG support.</span></li><li>${icon('check')}<span>A USB drive with enough free capacity.</span></li><li>${icon('check')}<span>USB-C directly or a data-capable OTG adapter.</span></li><li>${icon('check')}<span>Photos and videos available locally; cloud-only files may need downloading first.</span></li></ul></section><section id="steps"><p class="kicker">Safe workflow</p><h2>Copy photos in five steps</h2><ol><li>Unlock the phone, connect the drive and wait for Android to detect it.</li><li>Open FotoSafe and grant access to the media you want to copy. Partial access on Android 14+ may show selected files only.</li><li>Select the backup location and choose the USB drive in Android's system picker.</li><li>Review destination, new files, already backed-up files and required space.</li><li>Start the backup and keep the phone and drive connected until completion.</li></ol>${zoomImage('/assets/02-review-before-backup-en.webp','FotoSafe backup preview showing media counts and destination','FotoSafe shows the planned backup before it starts.')}</section><section id="verify"><p class="kicker">Afterwards</p><h2>Copying is not moving</h2><p>Originals remain on the phone. Open several new photos and large videos directly from the USB drive after the run.</p><div class="callout success"><strong>Verify before deleting anything elsewhere.</strong><p>A completion message is useful; a real file check is better.</p></div></section><section id="alternative"><p class="kicker">Honest alternative</p><h2>You can copy folders manually</h2><p>Android file managers can often copy folders such as <code>DCIM/Camera</code> to USB for free. FotoSafe is useful when you prefer a guided, repeatable preview and automatic skipping of files already backed up.</p></section><section id="repeat"><p class="kicker">Next time</p><h2>Back up again without starting from zero</h2><p>Reconnect the same destination for your next run. FotoSafe checks existing files and skips media already backed up, so you can focus on the new additions. Always review the destination and summary before copying.</p></section><section id="problems"><p class="kicker">Diagnosis</p><h2>If the drive does not appear</h2><ol><li>Reconnect and wait.</li><li>Check whether Android's own file manager sees USB storage.</li><li>Try a different data-capable adapter or smaller drive.</li><li>Consider power requirements.</li><li>Never format before safeguarding existing contents.</li></ol></section>`});

const enChoose=({icon})=>article({lang:'en',eyebrow:'Hardware guide',title:'Choose a USB drive for Android: five compatibility checks',lead:'A matching plug alone does not guarantee a working data connection.',answer:'Check the connector, USB OTG support, adapter data capability, file-system support and capacity. Direct USB-C is usually simplest.',read:'Reading time: about 6 minutes',icon,toc:[['start','Quick check'],['connect','Connection'],['storage','Storage'],['test','Test first'],['problems','Troubleshooting']],sections:`<section id="start"><p class="kicker">Quick check</p><h2>Five things to verify</h2><ul class="check-list"><li>${icon('check')}<span>USB-C direct or USB-A through USB-C OTG.</span></li><li>${icon('check')}<span>The adapter supports data, not charging only.</span></li><li>${icon('check')}<span>The phone supports USB host/OTG.</span></li><li>${icon('check')}<span>Capacity exceeds the planned backup with headroom.</span></li><li>${icon('check')}<span>The plug fits even with the phone case.</span></li></ul></section><section id="connect"><p class="kicker">Connection</p><h2>Direct USB-C reduces failure points</h2><p>A dual USB-C/USB-A drive works with many phones and computers. For USB-A, use a data-capable OTG adapter.</p></section><section id="storage"><p class="kicker">Storage</p><h2>Plan capacity and file-system support</h2><p>Video can dominate storage. Check FotoSafe's displayed data volume and leave spare capacity. Android support varies by device and file system. Formatting erases existing data and should never be the first troubleshooting step.</p></section><section id="test"><p class="kicker">Before a large run</p><h2>Confirm Android detects the drive</h2><p>Connect it, wait, open the system file manager and test a small file. If Android cannot see the drive, FotoSafe cannot select it either.</p></section><section id="problems"><p class="kicker">Troubleshooting</p><h2>USB drive not showing?</h2><ol><li>Unlock the phone, reconnect the drive and wait a few seconds.</li><li>Check the drive in Android's own file manager.</li><li>Remove the phone case if it prevents a complete connection.</li><li>Try a known data-capable OTG adapter or a lower-power drive.</li><li>Do not format the drive until existing files are safely copied elsewhere.</li></ol></section>`});

const enStrategy=({icon})=>article({lang:'en',eyebrow:'Backup basics',title:'Android photo backup: turn one copy into a resilient strategy',lead:'A USB copy is valuable, but no single drive is infallible. Multiple copies, verification and a repeatable routine matter.',answer:'Keep the originals, make at least one additional copy and store another important copy in a different location.',read:'Reading time: about 7 minutes',icon,toc:[['start','3-2-1'],['routine','Routine'],['verify','Verification'],['risks','Risks'],['next','Your next backup']],sections:`<section id="start"><p class="kicker">Principle</p><h2>Three copies, two media types, one elsewhere</h2><p>The 3-2-1 rule is a useful orientation. For personal photos, that might mean the phone, a USB copy and another trusted backup kept separately.</p></section><section id="routine"><p class="kicker">Routine</p><h2>A simple schedule beats a perfect plan</h2><p>Back up after important events and at regular intervals. FotoSafe skips files already backed up when you use the destination again.</p></section><section id="verify"><p class="kicker">Trust through checks</p><h2>Completion message plus spot checks</h2><p>Open several new photos and large videos directly from the destination. Occasionally check older files too.</p></section><section id="risks"><p class="kicker">Limits</p><h2>USB drives can fail, disappear or be damaged</h2><p>Do not keep every copy in the same bag or room. Protect drives containing private media and retain another separately stored copy.</p><ul class="check-list"><li>${icon('check')}<span>Check capacity and destination.</span></li><li>${icon('check')}<span>Do not disconnect during backup.</span></li><li>${icon('check')}<span>Open files from the destination afterwards.</span></li></ul></section><section id="next"><p class="kicker">Your next backup</p><h2>Make the safe action easy to repeat</h2><p>Choose a realistic interval, label the destination and keep enough free space. After important events, connect the drive, review the FotoSafe summary, copy, and open a few files from the destination. A small routine repeated consistently protects more than a perfect plan postponed forever.</p></section>`});

const enSupport=simple({eyebrow:'Direct support',title:'How can we help?',lead:'Most USB problems can be solved with the diagnostic steps. If not, contact FotoSafe directly by email.',body:`<section><h2>Check first</h2><ul><li>Does Android's file manager show the USB drive?</li><li>Is the OTG adapter data-capable?</li><li>Does the system picker show USB as the destination?</li><li>Is there enough free capacity?</li></ul><a class="button" href="/en/guides/back-up-android-photos-to-usb/#problems">Open troubleshooting</a></section><section><h2>Direct contact</h2><p>Include phone model, Android version, FotoSafe version, drive/adapter and the step where it fails. Do not attach private photos, videos or confidential files.</p><p><a class="button" href="mailto:fotosafe@weidisoft.net?subject=FotoSafe%20Support">fotosafe@weidisoft.net</a></p></section>`});
const enImprint=simple({eyebrow:'Provider information',title:'Imprint',lead:'Provider details for the FotoSafe website and Android app.',body:`<section><h2>Service provider and media owner</h2><address>Peter Weitgasser<br>Bsuch 123<br>A-5760 Saalfelden<br>Austria</address></section><section><h2>Contact</h2><p><a href="mailto:fotosafe@weidisoft.net">fotosafe@weidisoft.net</a></p></section><section><h2>Editorial purpose</h2><p>Information, guidance and support for the FotoSafe Android app and local photo and video backups.</p></section>`});
const enPrivacy=simple({eyebrow:'Privacy',title:'Privacy Policy for the FotoSafe app and website',lead:'Clear separation: the app processes media locally. The website requires no account or analytics cookies.',body:`<p><strong>Last updated:</strong> 12 September 2026 · <strong>Package:</strong> <code>at.weidi.fotobackup</code></p><section><h2>1. Summary</h2><ul><li>no FotoSafe account, advertising or tracking in the app,</li><li>no upload of your photos or videos to the app provider,</li><li>no deletion of originals,</li><li>no website analytics or analytics cookies.</li></ul></section><section><h2>2. Controller</h2><address>Peter Weitgasser<br>Bsuch 123<br>A-5760 Saalfelden<br>Austria<br><a href="mailto:privacy@weidisoft.net">privacy@weidisoft.net</a></address></section><section><h2>3. Local app processing</h2><p>After Android permission, FotoSafe reads photos, videos and associated file information to copy them to the storage location you select. Media copies, logs and index information are stored at that destination. Destination, last-backup and trial/Pro status are stored locally.</p><p>The app does not use general all-files access. Partial media access on Android 14+ may include selected files only.</p></section><section><h2>4. Google Play</h2><p>Installation, the one-time Pro purchase and restoration are handled by Google Play under Google's privacy terms. FotoSafe receives product, price and purchase-status information, not card details.</p></section><section><h2>5. Website hosting</h2><p>This static website is delivered through Cloudflare Pages. Cloudflare may process technically necessary connection and security data such as IP addresses. No analytics, advertising or tracking scripts are used. See the <a href="https://www.cloudflare.com/privacypolicy/" rel="noopener noreferrer">Cloudflare Privacy Policy</a>.</p></section><section><h2>6. Deletion and rights</h2><p>You remove backup copies at the selected destination. Local app data can be removed through Android settings or uninstallation; a Google Play purchase remains restorable through the Google account.</p><p>For access, rectification, erasure, restriction or objection, email <a href="mailto:privacy@weidisoft.net">privacy@weidisoft.net</a>. You may also complain to the Austrian Data Protection Authority.</p></section>`});

const notFound=(en=false)=>`<section class="simple-hero"><div class="shell narrow"><p class="eyebrow">404</p><h1>${en?'This page took the wrong USB turn.':'Diese Seite ist falsch abgebogen.'}</h1><p class="hero-lead">${en?'The address does not exist. The help centre will get you back on track.':'Diese Adresse gibt es nicht. Im Hilfebereich findest du den richtigen Einstieg.'}</p><p><a class="button" href="${en?'/en/help/':'/hilfe/'}">${en?'Open help':'Zur Hilfe'}</a> <a class="button button-secondary" href="${en?'/en/':'/'}">${en?'Home':'Startseite'}</a></p></div></section>`;
const bilingualNotFound=`<section class="simple-hero" lang="de"><div class="shell narrow"><p class="eyebrow">404 · Deutsch</p><h1>Diese Seite ist falsch abgebogen.</h1><p class="hero-lead">Diese Adresse gibt es nicht. Im Hilfebereich findest du den richtigen Einstieg.</p><p><a class="button" href="/hilfe/">Zur Hilfe</a> <a class="button button-secondary" href="/">Startseite</a></p></div></section><section class="section" lang="en"><div class="shell narrow"><p class="eyebrow">404 · English</p><h2>This page took the wrong USB turn.</h2><p class="hero-lead">The address does not exist. The help centre will get you back on track.</p><p><a class="button" href="/en/help/">Open help</a> <a class="button button-secondary" href="/en/">Home</a></p></div></section>`;

export function additionalPages({icon,playUrl,zoomImage,canonicalBase}){
 const schemaTag=value=>`<script type="application/ld+json">${JSON.stringify(value)}</script>`;
 const schemaContext='https:'+'//schema.org';
 const appSchema=appStructuredData({canonicalBase,playUrl});
 const guideBreadcrumbs=lang=>breadcrumbStructuredData(lang==='en'
  ? [{name:'Home',item:`${canonicalBase}/en/`},{name:'Guides',item:`${canonicalBase}/en/help/`}]
  : [{name:'Startseite',item:`${canonicalBase}/`},{name:'Ratgeber',item:`${canonicalBase}/hilfe/`}]);
 const pages=[
  {path:'/hilfe/',file:'hilfe/index.html',active:'/hilfe/',alternate:'/en/help/',title:'FotoSafe Hilfe & Ratgeber',description:'Anleitungen für FotoSafe, Android-USB-Backups, kompatible USB-Sticks und eine verlässliche Sicherungsstrategie.',content:deHelp+deLegacyFragmentHelp},
  {path:'/usb-stick-fuer-android-auswaehlen/',file:'usb-stick-fuer-android-auswaehlen/index.html',active:'/hilfe/',alternate:'/en/guides/choose-usb-drive-for-android/',title:'USB-Stick für Android auswählen | FotoSafe',description:'USB-C, OTG, Kapazität und Dateisystem: So wählst du einen passenden USB-Stick für Android-Backups.',content:deChoose({icon})},
  {path:'/foto-backup-strategie-android/',file:'foto-backup-strategie-android/index.html',active:'/hilfe/',alternate:'/en/guides/android-photo-backup-strategy/',title:'Fotos sichern ohne Cloud: Methodenvergleich | FotoSafe',description:'Lokale Foto-Backups ohne Cloud vergleichen: FotoSafe auf USB, Dateimanager, PC-Kopie und microSD mit Aufwand, Voraussetzungen und Grenzen.',content:deStrategy({icon}).replace('</aside>','<a href="#methoden">Methodenvergleich</a></aside>').replace('</article>',`${deMethodComparison}</article>`)},
  {path:'/support/',file:'support/index.html',active:'/support/',alternate:'/en/support/',title:'FotoSafe Support',description:'FotoSafe Support mit Fehlerhilfe und direktem E-Mail-Kontakt ohne Webformular.',content:deSupport},
  {path:'/impressum/',file:'impressum/index.html',alternate:'/en/imprint/',title:'Impressum | FotoSafe',description:'Anbieterinformationen und Kontakt für FotoSafe.',content:deImprint},
  {path:'/privacy/',file:'privacy/index.html',alternate:'/en/privacy/',title:'Datenschutzerklärung | FotoSafe',description:'Datenschutzerklärung für die lokal arbeitende FotoSafe-App und die statische FotoSafe-Website.',content:dePrivacy},
  {path:'/en/',file:'en/index.html',lang:'en',active:'/en/',alternate:'/',title:'FotoSafe — back up Android photos to USB',description:'Copy photos and videos straight from Android to USB without a computer, a FotoSafe media cloud or deleting originals.',content:enHome({icon,playUrl,zoomImage})},
  {path:'/en/help/',file:'en/help/index.html',lang:'en',active:'/en/help/',alternate:'/hilfe/',title:'FotoSafe help and guides',description:'Guides for FotoSafe, Android USB backups, compatible drives and a resilient backup strategy.',content:enHelp+enLegacyFragmentHelp},
  {path:'/en/guides/back-up-android-photos-to-usb/',file:'en/guides/back-up-android-photos-to-usb/index.html',lang:'en',active:'/en/help/',alternate:'/android-fotos-auf-usb-stick-sichern/',title:'Back up Android photos to USB | FotoSafe',description:'Copy Android photos to USB safely: requirements, destination selection, verification and troubleshooting.',content:enUsb({icon,zoomImage}).replace('</aside>','<a href="#file-manager-comparison">FotoSafe or file manager</a><a href="#destination-folder">Complete destination selection</a></aside>').replace('</article>',`${enFileManagerComparison}${enDestinationHelp}</article>`)},
  {path:'/en/guides/choose-usb-drive-for-android/',file:'en/guides/choose-usb-drive-for-android/index.html',lang:'en',active:'/en/help/',alternate:'/usb-stick-fuer-android-auswaehlen/',title:'Choose a USB drive for Android | FotoSafe',description:'Check USB-C, OTG, data support, capacity and file-system compatibility for Android photo backups.',content:enChoose({icon})},
  {path:'/en/guides/android-photo-backup-strategy/',file:'en/guides/android-photo-backup-strategy/index.html',lang:'en',active:'/en/help/',alternate:'/foto-backup-strategie-android/',title:'Back up photos without a cloud: method comparison | FotoSafe',description:'Compare local photo backups without a cloud: FotoSafe to USB, file manager, PC copy and microSD, including effort, requirements and limits.',content:enStrategy({icon}).replace('</aside>','<a href="#methods">Method comparison</a></aside>').replace('</article>',`${enMethodComparison}</article>`)},
  {path:'/en/support/',file:'en/support/index.html',lang:'en',active:'/en/support/',alternate:'/support/',title:'FotoSafe support',description:'FotoSafe troubleshooting and direct email support without a web form.',content:enSupport},
  {path:'/en/imprint/',file:'en/imprint/index.html',lang:'en',alternate:'/impressum/',title:'Imprint | FotoSafe',description:'Provider information and contact details for FotoSafe.',content:enImprint},
  {path:'/en/privacy/',file:'en/privacy/index.html',lang:'en',alternate:'/privacy/',title:'Privacy Policy | FotoSafe',description:'Privacy Policy for the locally operating FotoSafe app and static FotoSafe website.',content:enPrivacy},
  {path:'/404/',file:'404/index.html',alternate:'/en/404/',title:'Seite nicht gefunden | FotoSafe',description:'Die angeforderte FotoSafe-Seite wurde nicht gefunden.',content:notFound(false),noindex:true},
  {path:'/en/404/',file:'en/404/index.html',lang:'en',alternate:'/404/',title:'Page not found | FotoSafe',description:'The requested FotoSafe page was not found.',content:notFound(true),noindex:true},
  {path:'/404/',file:'404.html',alternate:'/en/404/',title:'Seite nicht gefunden / Page not found | FotoSafe',description:'Die angeforderte Seite wurde nicht gefunden. The requested page was not found.',content:bilingualNotFound,noindex:true}
 ];
 return pages.map(page=>{
  if(page.path==='/en/') return {...page,schema:schemaTag(appSchema)};
  if(page.path.includes('/guides/')||page.path==='/usb-stick-fuer-android-auswaehlen/'||page.path==='/foto-backup-strategie-android/') return {...page,schema:schemaTag({'@context':schemaContext,'@graph':[{'@type':'Article',headline:page.title.split(' | ')[0],description:page.description,inLanguage:page.lang||'de'},guideBreadcrumbs(page.lang||'de')]})};
  if(page.path==='/hilfe/'||page.path==='/en/help/') return {...page,schema:schemaTag({'@context':'https://schema.org','@type':'CollectionPage',name:page.title.split(' | ')[0],description:page.description,inLanguage:page.lang||'de'})};
  return page;
 });
}
const deMethodComparison=`<section id="methoden"><p class="kicker">Methodenvergleich</p><h2>Fotos ohne Cloud sichern: Welche lokale Methode passt?</h2><p>Keine lokale Methode ist automatisch ausfallsicher oder verschlüsselt. Entscheidend sind dein Gerät, deine Routine und mindestens eine weitere getrennte Kopie.</p><div class="comparison-table" role="region" aria-label="Vergleich lokaler Sicherungsmethoden" tabindex="0"><table><thead><tr><th>Methode</th><th>Aufwand</th><th>Kontrolle</th><th>Voraussetzungen</th><th>Verlustgrenze</th></tr></thead><tbody><tr><th>FotoSafe auf USB</th><td>Geführte Auswahl und wiederholbare Läufe</td><td>Vorschau, Zielanzeige und anschließende Stichprobe</td><td>Android-Gerät, erkannter USB-Speicher, bei Bedarf datenfähiger OTG-Adapter</td><td>Ein einzelner Stick kann ausfallen, beschädigt werden oder verloren gehen</td></tr><tr><th>Android-Dateimanager auf USB</th><td>Ordner und neue Dateien selbst auswählen</td><td>Direkte Ordnerkontrolle, Fortschritt und Dubletten selbst verwalten</td><td>System-Dateimanager mit USB-Kopierfunktion und Kenntnis der Medienordner</td><td>Übersehene Ordner oder eine falsche Auswahl bleiben ungesichert</td></tr><tr><th>PC-Kopie per USB-Kabel</th><td>Handy verbinden und Ordner am Computer kopieren</td><td>Zielordner, Dateizahl und Stichproben am PC selbst prüfen</td><td>Computer, datenfähiges Kabel, entsperrtes Handy und freigegebene Dateiübertragung</td><td>Die PC-Kopie schützt nicht vor Verlust, Defekt oder Schadsoftware am selben Computer</td></tr><tr><th>microSD-Kopie, falls unterstützt</th><td>Je nach Gerät manuell oder per Dateimanager</td><td>Speicherkarte bleibt lokal und herausnehmbar</td><td>Gerät mit microSD-Steckplatz und kompatible Speicherkarte</td><td>Nicht auf jedem Gerät verfügbar; Karte kann mit dem Handy verloren gehen oder ausfallen</td></tr></tbody></table></div><p>Für eine geführte USB-Kopie lies die <a href="/android-fotos-auf-usb-stick-sichern/">vollständige USB-Anleitung</a>. Die <a href="/">FotoSafe-Produktseite</a> erklärt, was die App übernimmt. Wenn du PC oder Dateimanager nutzt, prüfe danach immer Dateien direkt am Ziel.</p></section>`;

const enMethodComparison=`<section id="methods"><p class="kicker">Method comparison</p><h2>Back up photos without a cloud: which local method fits?</h2><p>No local method is automatically failure-proof or encrypted. Your device, routine and at least one separately stored copy determine the real protection.</p><div class="comparison-table" role="region" aria-label="Comparison of local backup methods" tabindex="0"><table><thead><tr><th>Method</th><th>Effort</th><th>Control</th><th>Requirements</th><th>Loss limit</th></tr></thead><tbody><tr><th>FotoSafe to USB</th><td>Guided selection and repeatable runs</td><td>Preview, destination display and a spot check afterwards</td><td>Android device, USB storage recognised by Android and, if needed, a data-capable OTG adapter</td><td>One drive can fail, be damaged or be lost</td></tr><tr><th>Android file manager to USB</th><td>Select folders and new files yourself</td><td>Direct folder control; you manage progress and duplicates</td><td>A system file manager that can copy to USB and knowledge of your media folders</td><td>Missed folders or a wrong selection remain unprotected</td></tr><tr><th>PC copy via USB cable</th><td>Connect the phone and copy folders on the computer</td><td>Check the destination, file count and samples on the PC</td><td>Computer, data-capable cable, unlocked phone and enabled file transfer</td><td>The PC copy does not protect against loss, failure or malware on that same computer</td></tr><tr><th>microSD copy, if supported</th><td>Manual or file-manager copy depending on the device</td><td>The removable card stays under your control</td><td>A phone with a microSD slot and a compatible card</td><td>Unavailable on many phones; the card can fail or disappear with the phone</td></tr></tbody></table></div><p>For a guided USB copy, follow the <a href="/en/guides/back-up-android-photos-to-usb/">complete USB guide</a>. The <a href="/en/">FotoSafe product page</a> explains what the app handles. With a PC or file manager, always open files from the destination afterwards.</p></section>`;

const enFileManagerComparison=`<section id="file-manager-comparison"><p class="kicker">Decision aid</p><h2>FotoSafe or a file manager: compare the work before you choose</h2><p>A system file manager usually adds no purchase cost, but you select folders, track progress and resolve duplicates yourself. FotoSafe offers a guided preview and repeatable runs; one successful run with up to 100 media files is free, then further runs require the one-time Pro purchase.</p><div class="comparison-table" role="region" aria-label="Comparison of FotoSafe and file manager" tabindex="0"><table><thead><tr><th scope="col">Decision</th><th scope="col">FotoSafe</th><th scope="col">File manager</th></tr></thead><tbody><tr><th scope="row">Workflow</th><td>Guided destination, media preview and summary before copying</td><td>Find and select media folders manually</td></tr><tr><th scope="row">Later runs</th><td>Already backed-up files are identified and skipped</td><td>You decide which files conflict or need copying again</td></tr><tr><th scope="row">Control</th><td>Review selected counts and destination before starting</td><td>Inspect folders and copied files yourself</td></tr><tr><th scope="row">Cost</th><td>One free successful trial run; then a one-time Pro purchase</td><td>Android system function, usually at no extra purchase cost</td></tr><tr><th scope="row">Access</th><td>Needs access to the photos and videos you choose to back up</td><td>Needs access granted through the file manager and Android picker</td></tr></tbody></table></div></section>`;

const enDestinationHelp=`<section id="destination-folder"><p class="kicker">Android system picker</p><h2>Choose the destination folder through the final permission step</h2><ol><li>In FotoSafe, tap <strong>“Choose backup location”</strong> or <strong>“Change backup location”</strong>. The next file picker belongs to Android; its layout and labels vary by Android version and manufacturer.</li><li>Open the side panel or storage overview if needed. Choose the connected USB storage entry, not the device name or <strong>“Internal storage”</strong>.</li><li>On the USB storage, open an existing backup folder or create a dedicated folder such as <code>FotoSafe</code>.</li><li>Check the storage and folder shown at the top. Tap <strong>“Use this folder”</strong>, then confirm the Android prompt with <strong>“Allow”</strong>.</li><li>Back in FotoSafe, confirm that the displayed destination matches the USB drive before reviewing or copying media.</li></ol><div class="compare"><div class="good"><b>Correct storage choice</b><p>The USB volume name or an unambiguous USB label appears in the storage list or path, with your chosen folder beneath it.</p></div><div class="bad"><b>Wrong storage choice</b><p>The phone name, “Internal storage”, “Downloads” or “DCIM” is the top-level storage. Cancel and start again from the USB entry.</p></div></div><h3>If USB is not listed</h3><ul><li>Cancel, reconnect the drive and data-capable OTG adapter, then wait briefly.</li><li>Check the manufacturer's file manager. If Android does not show the USB storage there, FotoSafe cannot select it.</li><li>Do not format on a guess. Check the connection, adapter, power demand and compatibility first; formatting erases data.</li><li>If “Use this folder” is disabled, do not force the storage root. Open or create a subfolder on the USB drive.</li><li>If you denied “Allow” or selected the wrong destination, reopen destination selection in FotoSafe.</li></ul><h3>Check full media access</h3><p>Android 14 and later may initially expose only selected photos and videos. If FotoSafe cannot see all media you intend to copy, open device <strong>Settings</strong> and look under <strong>Apps → FotoSafe → Permissions → Photos and videos</strong> for an option covering all photos and videos. Exact wording varies; grant only the scope you intend to back up.</p><h3>Samsung/One UI fallback</h3><p>On some Samsung devices, first open <strong>My Files</strong> and check whether “USB storage” or the volume name appears. Return to destination selection and open that same entry from the storage overview. <strong>Galaxy S23 is only an example</strong> represented by the existing German captures; it does not prove identical UI across Samsung, One UI or Android releases.</p><div class="callout warning"><strong>Existing captures are not treated as universal evidence.</strong><p>They show German FotoSafe/Galaxy-S23 examples but provide no capture date, English equivalent or proof of identical screens on other devices. The steps therefore teach observable decisions and explicitly variable system labels instead of promising one fixed layout.</p></div></section>`;

const deLegacyFragmentHelp=`<section class="section shell legacy-help" aria-labelledby="legacy-help-title"><div class="section-heading"><p class="kicker">Direkteinstiege aus der bisherigen Hilfe</p><h2 id="legacy-help-title">Bekannte Hilfe-Links führen weiter zum passenden Inhalt</h2><p>Alte Lesezeichen behalten ihr Fragment nach der Weiterleitung. Diese statischen Ziele funktionieren deshalb auch ohne JavaScript.</p></div><div class="guide-grid"><article id="anleitung" class="guide-card"><h3>Schritt-für-Schritt-Anleitung</h3><p>Vom Erkennen des USB-Speichers bis zur abschließenden Freigabe.</p><a href="/android-fotos-auf-usb-stick-sichern/#schritte">Vollständige Anleitung öffnen →</a></article><article id="medienzugriff" class="guide-card"><h3>Medienzugriff</h3><p>Teilzugriff, vollständiger Zugriff und der variable Weg durch die Android-Einstellungen.</p><a href="/android-fotos-auf-usb-stick-sichern/#zielordner">Medienzugriff prüfen →</a></article><article id="video" class="guide-card"><h3>Ordnerwahl ohne veraltetes Video</h3><p>Die frühere Videoanleitung wird durch gepflegte Textschritte ersetzt; vorhandene Aufnahmen sind nicht als aktueller allgemeiner Gerätebeleg freigegeben.</p><a href="/android-fotos-auf-usb-stick-sichern/#zielordner">Aktuelle Ordnerwahl lesen →</a></article><article id="probleme" class="guide-card"><h3>USB-Probleme lösen</h3><p>Erkennung, Adapter, Strombedarf und sichere nächste Schritte.</p><a href="/android-fotos-auf-usb-stick-sichern/#probleme">Fehlerdiagnose öffnen →</a></article><article id="otg" class="guide-card"><h3>OTG verstehen</h3><p>Prüfe Anschluss, Datenfähigkeit und Geräteunterstützung.</p><a href="/usb-stick-fuer-android-auswaehlen/#anschluss">OTG- und Anschlussratgeber öffnen →</a></article><article id="auswahlhilfe" class="guide-card"><h3>Hardware auswählen</h3><p>Neutrale Kriterien statt ungeprüfter Produktempfehlungen.</p><a href="/usb-stick-fuer-android-auswaehlen/#start">Auswahlhilfe öffnen →</a></article><article id="cat-otg" class="guide-card"><h3>OTG-Adapter</h3><p>Datenfähige Adapter und passende Stecker beurteilen.</p><a href="/usb-stick-fuer-android-auswaehlen/#anschluss">Adapterkriterien öffnen →</a></article><article id="cat-usbc" class="guide-card"><h3>USB-C-Speicher</h3><p>Direkte USB-C-Verbindungen und Kompatibilität prüfen.</p><a href="/usb-stick-fuer-android-auswaehlen/#anschluss">USB-C-Kriterien öffnen →</a></article><article id="cat-usba" class="guide-card"><h3>USB-A-Speicher</h3><p>USB-A-Sticks benötigen am Handy in der Regel einen passenden datenfähigen Adapter.</p><a href="/usb-stick-fuer-android-auswaehlen/#anschluss">USB-A-Kriterien öffnen →</a></article><article id="cat-phone" class="guide-card"><h3>Android-Gerät</h3><p>OTG-Unterstützung, Dateisystem und Strombedarf sind geräteabhängig.</p><a href="/usb-stick-fuer-android-auswaehlen/#start">Gerätekriterien öffnen →</a></article></div></section>`;

const enLegacyFragmentHelp=`<section class="section shell legacy-help" aria-labelledby="legacy-help-title"><div class="section-heading"><p class="kicker">Direct entries from the previous help page</p><h2 id="legacy-help-title">Known help links still reach the relevant content</h2><p>Old bookmarks retain their fragment after the redirect. These static targets therefore work without JavaScript.</p></div><div class="guide-grid"><article id="anleitung" class="guide-card"><h3>Step-by-step guide</h3><p>From recognising USB storage through the final permission prompt.</p><a href="/en/guides/back-up-android-photos-to-usb/#steps">Open the complete guide →</a></article><article id="media-access" class="guide-card"><h3>Media access</h3><p>Selected-media access, full access and the variable Android Settings route.</p><a href="/en/guides/back-up-android-photos-to-usb/#destination-folder">Check media access →</a></article><article id="video" class="guide-card"><h3>Folder selection without an outdated video</h3><p>The former video is replaced by maintained text steps; existing captures are not cleared as current universal device evidence.</p><a href="/en/guides/back-up-android-photos-to-usb/#destination-folder">Read the current folder steps →</a></article><article id="probleme" class="guide-card"><h3>Solve USB problems</h3><p>Recognition, adapters, power demand and safe next steps.</p><a href="/en/guides/back-up-android-photos-to-usb/#problems">Open troubleshooting →</a></article><article id="otg" class="guide-card"><h3>Understand OTG</h3><p>Check the connector, data capability and device support.</p><a href="/en/guides/choose-usb-drive-for-android/#connect">Open OTG and connector guidance →</a></article><article id="auswahlhilfe" class="guide-card"><h3>Choose hardware</h3><p>Neutral criteria instead of unverified product recommendations.</p><a href="/en/guides/choose-usb-drive-for-android/#start">Open selection guidance →</a></article><article id="cat-otg" class="guide-card"><h3>OTG adapters</h3><p>Assess data-capable adapters and matching connectors.</p><a href="/en/guides/choose-usb-drive-for-android/#connect">Open adapter criteria →</a></article><article id="cat-usbc" class="guide-card"><h3>USB-C storage</h3><p>Check direct USB-C connections and compatibility.</p><a href="/en/guides/choose-usb-drive-for-android/#connect">Open USB-C criteria →</a></article><article id="cat-usba" class="guide-card"><h3>USB-A storage</h3><p>USB-A drives generally need a matching data-capable adapter at the phone.</p><a href="/en/guides/choose-usb-drive-for-android/#connect">Open USB-A criteria →</a></article><article id="cat-phone" class="guide-card"><h3>Android device</h3><p>OTG support, file systems and power demand vary by device.</p><a href="/en/guides/choose-usb-drive-for-android/#start">Open device criteria →</a></article></div></section>`;
